<script setup lang="ts">
import type { TableColumn } from '@nuxt/ui'
definePageMeta({ layout: 'dashboard' })
interface Review { id: number, rating: number, comment: string, status: 'PENDING' | 'APPROVED' | 'RETURNED' | 'HIDDEN', reviewerNote: string | null, studentUser: { loginId: string, prefix: string, firstName: string, lastName: string }, cooperativeRequest: { companyName: string, province: string | null } }
const { data, status, refresh } = await useFetch<Review[]>('/api/staff/company-reviews')
const notify = useNotify(); const search = ref(''); const statusFilter = ref<'ALL' | Review['status']>('PENDING'); const selected = ref<Review | null>(null); const open = ref(false); const reviewerNote = ref(''); const saving = ref(false)
const filtered = computed(() => (data.value ?? []).filter(item => (statusFilter.value === 'ALL' || item.status === statusFilter.value) && [item.cooperativeRequest.companyName, item.studentUser.loginId, item.studentUser.firstName, item.studentUser.lastName].join(' ').toLowerCase().includes(search.value.trim().toLowerCase())))
const statusInfo = (value: Review['status']) => ({ PENDING: { label: 'รอตรวจสอบ', color: 'warning' as const }, APPROVED: { label: 'เผยแพร่แล้ว', color: 'success' as const }, RETURNED: { label: 'ส่งกลับแก้ไข', color: 'error' as const }, HIDDEN: { label: 'ซ่อน', color: 'neutral' as const } }[value])
const inspect = (review: Review) => { selected.value = review; reviewerNote.value = review.reviewerNote || ''; open.value = true }
const updateStatus = async (nextStatus: Review['status']) => { if (!selected.value) return; saving.value = true; try { await $fetch(`/api/staff/company-reviews/${selected.value.id}`, { method: 'PATCH', body: { status: nextStatus, reviewerNote: reviewerNote.value } }); notify.success('อัปเดตสถานะรีวิวเรียบร้อยแล้ว'); open.value = false; await refresh() } catch (err: any) { notify.error(err?.data?.message || 'ไม่สามารถอัปเดตรีวิวได้') } finally { saving.value = false } }
const columns: TableColumn<Review>[] = [{ id: 'student', header: 'นักศึกษา' }, { id: 'company', header: 'สถานประกอบการ' }, { id: 'rating', header: 'คะแนน' }, { id: 'status', header: 'สถานะ' }, { id: 'actions', header: 'จัดการ', meta: { class: { th: 'w-28 text-end', td: 'w-28 text-end' } } }]
</script>
<template><UDashboardPanel id="staff-company-reviews"><template #header><AppDashboardNavbar title="จัดการรีวิวสถานประกอบการ"><template #leading><UDashboardSidebarCollapse /></template></AppDashboardNavbar></template><template #body><div class="space-y-4 p-4 sm:p-6"><UCard :ui="{ body: 'p-0' }"><div class="border-b border-divider p-5 sm:p-6"><h2 class="text-lg font-bold text-ink">รีวิวจากนักศึกษา</h2><p class="mt-1 text-sm text-muted">ตรวจสอบ อนุมัติ ส่งกลับแก้ไข หรือซ่อนรีวิวก่อนเผยแพร่</p><div class="mt-4 flex flex-wrap gap-2"><UInput v-model="search" size="xl" icon="i-lucide-search" placeholder="ค้นหานักศึกษาหรือสถานประกอบการ" class="w-full sm:w-80" /><USelect v-model="statusFilter" :items="[{ label: 'ทั้งหมด', value: 'ALL' }, { label: 'รอตรวจสอบ', value: 'PENDING' }, { label: 'เผยแพร่แล้ว', value: 'APPROVED' }, { label: 'ส่งกลับแก้ไข', value: 'RETURNED' }, { label: 'ซ่อน', value: 'HIDDEN' }]" value-key="value" size="xl" class="w-44" /><UIButtonRefresh :loading="status === 'pending'" @refresh="refresh" /></div></div><UTable :data="filtered" :columns="columns" class="min-w-full"><template #student-cell="{ row }"><span>{{ row.original.studentUser.prefix }}{{ row.original.studentUser.firstName }} {{ row.original.studentUser.lastName }}</span><p class="text-xs text-muted">{{ row.original.studentUser.loginId }}</p></template><template #company-cell="{ row }"><span>{{ row.original.cooperativeRequest.companyName }}</span><p class="text-xs text-muted">{{ row.original.cooperativeRequest.province || '—' }}</p></template><template #rating-cell="{ row }"><span class="tabular-nums">{{ row.original.rating }}/5</span></template><template #status-cell="{ row }"><UBadge :color="statusInfo(row.original.status).color" variant="subtle">{{ statusInfo(row.original.status).label }}</UBadge></template><template #actions-cell="{ row }"><div class="flex justify-end"><UButton label="ตรวจสอบ" size="xs" color="primary" variant="ghost" @click="inspect(row.original)" /></div></template></UTable><UEmpty v-if="!filtered.length && status !== 'pending'" icon="i-lucide-message-square" title="ไม่พบรีวิว" class="py-12" /></UCard></div></template></UDashboardPanel><UModal v-model:open="open" :title="selected ? `รีวิว ${selected.cooperativeRequest.companyName}` : 'ตรวจสอบรีวิว'"><template #body><div v-if="selected" class="space-y-4"><div class="rounded-panel bg-surface p-4"><p class="font-medium text-ink">{{ selected.rating }}/5 คะแนน</p><p class="mt-2 whitespace-pre-wrap text-sm text-muted">{{ selected.comment }}</p></div><UFormField label="หมายเหตุถึงนักศึกษา"><UTextarea v-model="reviewerNote" size="xl" class="w-full" /></UFormField></div></template><template #footer><div class="flex flex-wrap justify-end gap-2"><UButton label="ซ่อน" color="neutral" variant="outline" size="xl" :loading="saving" @click="updateStatus('HIDDEN')" /><UButton label="ส่งกลับแก้ไข" color="error" variant="outline" size="xl" :loading="saving" @click="updateStatus('RETURNED')" /><UButton label="อนุมัติเผยแพร่" color="success" size="xl" :loading="saving" @click="updateStatus('APPROVED')" /></div></template></UModal></template>
